        ==> (p EXP m divides iterate (\m n:num. lcm(m,n)) k f <=>
             m = 0 \/
             FINITE {j | j IN k /\ ~(f j = 1)} /\
             ?i. i IN k /\ p EXP m divides (f i))`;;

let PRIME_DIVIDES_ITERATE_LCM_GEN = `!f (k:K->bool) p.
