let REAL_INF_LT_FINITE = `!s a. FINITE s /\ ~(s = {}) ==> (inf s < a <=> ?x. x IN s /\ x < a)`;;

let REAL_INF_UNIQUE = `!s b. (!x. x IN s ==> b <= x) /\
