let REAL_LE_INF = `!b. ~(s = {}) /\ (!x. x IN s ==> b <= x) ==> b <= inf s`;;

let REAL_LE_INF_SUBSET = `!s t. ~(t = {}) /\ t SUBSET s /\ (?b. !x. x IN s ==> b <= x)
