let INF_UNIQUE = `!s b. (!c. (!x. x IN s ==> c <= x) <=> c <= b) ==> inf s = b`;;

let INF_UNION = `!s t. ~(s = {}) /\ ~(t = {}) /\
         (?b. !x. x IN s ==> b <= x) /\ (?c. !x. x IN t ==> c <= x)
