let FORALL_1 = `(!i. 1 <= i /\ i <= 1 ==> P i) <=> P 1`;;

let FORALL_2 = `!P. (!i. 1 <= i /\ i <= 2 ==> P i) <=> P 1 /\ P 2`;;

let FORALL_3 = `!P. (!i. 1 <= i /\ i <= 3 ==> P i) <=> P 1 /\ P 2 /\ P 3`;;

let FORALL_4 = `!P. (!i. 1 <= i /\ i <= 4 ==> P i) <=> P 1 /\ P 2 /\ P 3 /\ P 4`;;

let SUM_1 = `sum(1..1) f = f(1)`;;

