let DROP_IN_IMAGE_DROP = `!x s. (drop x) IN (IMAGE drop s) <=> x IN s`;;

let LIFT_NUM = `!n. lift(&n) = vec n`;;

let LIFT_ADD = `!x y. lift(x + y) = lift x + lift y`;;

let LIFT_SUB = `!x y. lift(x - y) = lift x - lift y`;;

